  FT["PH-H6057"] = {"id":"PH-H6057","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7574_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Lupi市","en":"An Act Converting the Rural Health Unit in the Municipality of Lupi, Province of Camarines Sur, Into A Five-bed Capacity Health Infirmary, To Be Known As the Lupi Health Infirmary, and Appropriating Funds Therefor","orig":"An Act Converting the Rural Health Unit in the Municipality of Lupi, Province of Camarines Sur, Into A Five-bed Capacity Health Infirmary, To Be Known As the Lupi Health Infirmary, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7574","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-26","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7574_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6057-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The rural health unit in the Municipality of Lupi, Province of Camarines Sur, is hereby converted into a five-bed capacity health infirmary, to be known as the Lupi Health Infirmary."}},{"id":"PH-H6057-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6057-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p86"};
  FT["PH-H6058"] = {"id":"PH-H6058","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7575_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Sapang Dalaga市","en":"An Act Converting the Rural Health Unit in the Municipality of Sapang Dalaga, Province of Misamis Occidental, Into A Five-bed Capacity Health Infirmary, To Be Known As the Sapang Dalaga Health Infirmary, and Appropriating Funds Therefor","orig":"An Act Converting the Rural Health Unit in the Municipality of Sapang Dalaga, Province of Misamis Occidental, Into A Five-bed Capacity Health Infirmary, To Be Known As the Sapang Dalaga Health Infirmary, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7575","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-26","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7575_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6058-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The rural health unit in the Municipality of Sapang Dalaga, Province of Misamis Occidental, is hereby converted into a five-bed capacity health infirmary, to be known as the Sapang Dalaga Health Infirmary."}},{"id":"PH-H6058-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6058-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p86"};
  FT["PH-H6059"] = {"id":"PH-H6059","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7576_1992.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"授予 Cotabato 电视公司在哥打巴托市及马京达瑙等省为商业、教育与文化目的建设、运营和维护广播电视站并为其他目的法案","en":"An Act Granting the Cotabato Television Corporation A Franchise To Construct, Install, Operate and Maintain For Commercial, Educational and Cultural Purposes Radio and Television Broadcasting Stations in the City of Cotabato and the Provinces of Maguindanao, Sultan Kudarat and North Cotabato and For Other Purposes","orig":"An Act Granting the Cotabato Television Corporation A Franchise To Construct, Install, Operate and Maintain For Commercial, Educational and Cultural Purposes Radio and Television Broadcasting Stations in the City of Cotabato and the Provinces of Maguindanao, Sultan Kudarat and North Cotabato and For Other Purposes"},"level":"law","status":"active","topics":["investment","trade","education"],"docNumber":"Republic Act No. 7576","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-26","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7576_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6059-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. – Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Cotabato Television Corporation, hereunder referred to as the grantee, its successors or assigns a franchise to construct, install, operate and maintain for commercial, educational and cultural purposes and in the public interest radio and television broadcasting stations in the City of Cotabato and the Provinces of Maguindanao, Sultan Kudarat and North Cotabato with the corresponding technological auxiliaries or facilities, special broadcast and other program and distribution services and relay stations, and to install radio communication facilities for the grantee's private use in its broadcast services."}},{"id":"PH-H6059-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. – The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the other existing stations or stations which may be established in accordance with law of other telecommunications services grantees without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H6059-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. – The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio/television spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H6059-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. – The grantee shall provide reasonable public service time to enable the Government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; promote public participation such as in community programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation to the detriment of the public interest, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H6059-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. – The President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, may temporarily take over and operate the stations of the grantee, temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or authorize the temporary use and operation thereof by any agency of the Government, upon due compensation to the grantee, for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H6059-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. – This franchise shall be for a term of twenty-five (25) years from the date of the effectivity of this Act, unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H6059-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. – Acceptance of this franchise shall be given in writing within sixty (60) days, after approval of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H6059-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provisions. – The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the radio/television business transacted under this franchise by the grantee, its successors or assigns and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof-. Provided That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6059-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Democratization of Ownership. – In compliance with the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make public offering through the stock exchanges of at least thirty percent (30%) of its common stock within a period of three (3) years from the date of effectivity of this Act: Provided, That no single person or entity shall be allowed to own more than five percent (5%) of the stock offerings."}},{"id":"PH-H6059-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. – The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H6059-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. – The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or entity, nor merge with any other corporation or entity without the prior approval of the Congress of the Philippines. Neither shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H6059-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Separability Clause . – If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H6059-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Repealing and Non-exclusivity Clause. – This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H6059-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"General Broadcast Policy. – The grantee shall comply with and be subject to the provisions of a general broadcast policy law that may hereafter be enacted."}},{"id":"PH-H6059-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Reportorial Requirement. – The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H6059-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p86","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Cotabato Television Corporation A Franchise To Construct, Install, Operate and Maintain For Commercial, Educational and Cultural Purposes Radio and Television Broadcasting Stations in the City of Cotabato and the Provinces of Maguindanao, Sultan Kudarat and North Cotabato and For Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6060"] = {"id":"PH-H6060","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7577_1992.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"授予 Majlis Al Da'wah Al Islamiah 机构在棉兰老设立、运营和维护广播电视站的特许经营权法案","en":"An Act Granting To the Majlis Al Da'wah Al Islamiah Fil-philippines, Inc., A Franchise To Establish, Operate and Maintain Radio and Television Broadcasting Stations in Mindanao","orig":"An Act Granting To the Majlis Al Da'wah Al Islamiah Fil-philippines, Inc., A Franchise To Establish, Operate and Maintain Radio and Television Broadcasting Stations in Mindanao"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 7577","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-27","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7577_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6060-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. – Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Majlis Al Da'Wah Al Islamiah Fil-Philippines, Inc., its successors or assigns and hereunder referred to as the grantee, a franchise to construct, establish, operate and maintain radio and television broadcasting stations in Mindanao with the corresponding technological auxiliaries or facilities, special broadcast and other broadcast distribution services and relay stations, and to install radio communication facilities for the grantee's private use in its broadcast services."}},{"id":"PH-H6060-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. – The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the existing stations or other stations which may be established by law."}},{"id":"PH-H6060-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. – The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio/television spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H6060-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. – The grantee shall provide reasonable public service time to enable the Government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; promote public participation such as in community programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation to the detriment of the public interest, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H6060-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. – The President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, may temporarily take over and operate the stations of the grantee, temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or authorize the temporary use and operation thereof by any agency of the Government, upon due compensation to the grantee, for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H6060-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. – This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act, unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H6060-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. – Acceptance of this franchise shall be given in writing within sixty (60) days after the approval of this Act. Refusal or failure to accept the franchise or to operate within the prescribed period shall render the franchise void."}},{"id":"PH-H6060-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provisions. – The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property exclusive of this franchise, as other persons or corporations which are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the radio/television business transacted under this franchise by the grantee, its successors or assigns and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code. The return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6060-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Democratization of Ownership. – In compliance with the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make public offering through the stock exchanges of at least thirty percent (30%) of its common stock within a period of three (3) years from the date of effectivity of this Act: Provided, That no single person or entity shall be allowed to own more than five percent (5%) of the stock offerings."}},{"id":"PH-H6060-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. – The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H6060-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. – The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or entity, nor merge with any other corporation or entity without the prior approval of the Congress of the Philippines. Neither shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is validly sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitation of this Act."}},{"id":"PH-H6060-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Separability Clause . – If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H6060-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Repealing and Non-exclusivity Clause. – This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H6060-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"General Broadcast Policy. – The grantee shall comply with and be subject to the provisions of a general broadcast policy law that may hereafter be enacted."}},{"id":"PH-H6060-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Reportorial Requirement. – The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H6060-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p86","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting To the Majlis Al Da'wah Al Islamiah Fil-philippines, Inc., A Franchise To Establish, Operate and Maintain Radio and Television Broadcasting Stations in Mindanao","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6061"] = {"id":"PH-H6061","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7578_1992.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"授予 Ibaan 电力与工程公司在八打雁省 Ibaan 市镇建设、运营和维护电灯、供热与动力系统的特许经营权法案，并为其他目的","en":"An Act Granting the Ibaan Electric and Engineering Corporation A Franchise To Construct, Operate and Maintain An Electric Light, Heat and Power System in the Municipality of Ibaan, Province of Batangas, and For Other Purposes","orig":"An Act Granting the Ibaan Electric and Engineering Corporation A Franchise To Construct, Operate and Maintain An Electric Light, Heat and Power System in the Municipality of Ibaan, Province of Batangas, and For Other Purposes"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 7578","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-27","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7578_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6061-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution and the provisions of laws, orders or issuances not inconsistent herewith, the Ibaan Electric and Engineering Corporation, hereunder referred to as the grantee, its successors or assigns, is hereby granted a franchise to construct, operate and maintain an electric light, heat and power system for the purpose of generating and/or distributing electric light, heat and power system for sale in the Municipality of lbaan, Province of Batangas, for a period of twenty-five (25) years from the date of effectivity of this Act."}},{"id":"PH-H6061-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The grantee shall have the right and privilege to install, lay and maintain on all streets, public thoroughfares, bridges and public places within the territory covered by this franchise, poles, wires, transformers, capacitors, overhead protective devices, pole line hardware and other equipment necessary for the safe distribution of electric current to the public. The grantee shall have the corresponding duty to restore to their original condition the public place or places so affected by such installation and/or construction."}},{"id":"PH-H6061-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"At such time that the National Power Corporation shall have established its line in the areas adjacent to or over the territory covered by this franchise, it shall make available its power and heat only after negotiations with and through or with the authority and consent of the grantee which shall be the exclusive distributor of whatever power the aforesaid corporation may make available to adjacent areas or within the territory covered by this franchise."}},{"id":"PH-H6061-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee shall undertake the electrification of all unenergized barangays in the Municipality of Ibaan, Province of Batangas, within the radius of five kilometers (5 km.) from its existing lines within five (5) years and the remaining unenergized barangays in the said municipality within fifteen (15) years from the effectivity of this Act.\nShould there be applications for connections within an unenergized barangay from more than one hundred (100) households, the grantee is obligated to accelerate the electrification and to provide electric service within a year of application."}},{"id":"PH-H6061-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The rates for the sale of electricity, heat and power by the grantee to its consumers shall be subject to the regulations of the Energy Regulatory Board.\nThe Energy Regulatory Board (ERB) may also impose fines or penalties to the grantee should the latter fail to live up to its business expansion plan indicated in Section 4 herein."}},{"id":"PH-H6061-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"In the event that the Government should desire to operate and maintain for itself the system herein authorized, the grantee shall surrender its franchise and shall turn over to the Government all its equipment at fair market value."}},{"id":"PH-H6061-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"In consideration of the franchise and privileges herein granted, the grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns, shall pay a franchise tax equivalent to two percent (2%) of all gross receipts of the electric business transacted under this franchise or earnings thereof - Provided That the grantee, its successors or assigns shall be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6061-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or entity, nor merge with any other corporation or entity without the prior approval of the Congress of the Philippines. Neither shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is validly sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H6061-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"This franchise herein granted shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H6061-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee shall submit an annual accomplishment report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H6061-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p86","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Ibaan Electric and Engineering Corporation A Franchise To Construct, Operate and Maintain An Electric Light, Heat and Power System in the Municipality of Ibaan, Province of Batangas, and For Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6062"] = {"id":"PH-H6062","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7579_1992.html","fetchedAt":"2026-10-06","articleCount":17,"structureMode":"ARTICLE","title":{"zh":"授予 Radio Veritas-Global 广播公司在菲律宾为宗教、教育、文化及商业目的建设、运营和维护广播电视站并为其他目的法案","en":"An Act Granting the Radio Veritas-global Broadcasting System, Incorporated, A Franchise To Construct, Install, Operate and Maintain For Religious, Educational, Cultural and Commercial Purposes Radio and Television Broadcasting Stations in the Philippines, and For Other Purposes","orig":"An Act Granting the Radio Veritas-global Broadcasting System, Incorporated, A Franchise To Construct, Install, Operate and Maintain For Religious, Educational, Cultural and Commercial Purposes Radio and Television Broadcasting Stations in the Philippines, and For Other Purposes"},"level":"law","status":"active","topics":["investment","company","trade"],"docNumber":"Republic Act No. 7579","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-27","completenessNote":"全文，共 17 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7579_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6062-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. – Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Radio Veritas-Global Broadcasting System, Incorporated, hereunder referred to as the grantee, a franchise to construct, install, operate and maintain for religious, educational, cultural and commercial purposes and in the public interest radio broadcasting stations and television stations in the Philippines with the corresponding technological auxiliaries or facilities, special broadcast and other program, distribution services and relay stations."}},{"id":"PH-H6062-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. – The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the other existing stations or stations which may be established by law without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H6062-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio and television spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H6062-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. – The grantee shall provide reasonable public service time to enable the Government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; promote public participation such as in community programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, or speech, or for the dissemination of deliberately false information or willful misrepresentation to the detriment of the public interest, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H6062-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. – The President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, may temporarily take over and operate the stations of the grantee, temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or authorize the temporary use and operation thereof by any agency of the Government, upon due compensation to the grantee, for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H6062-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. – This franchise shall be for a term of twenty-five (25) years from the date of the effectivity of this Act, unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H6062-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. – Acceptance of this franchise shall be given in writing within sixty (60) days after approval of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H6062-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provisions. – The grantee, its successors or assigns, shall be liable to pay the same taxes on its real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns, shall pay a franchise tax equivalent to three and a-half percent (3.5%) of all gross receipts of the radio business transacted under this franchise by the grantee, its successors or assigns and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: Provided, That the grantee, its successors or assigns, shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6062-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Public Ownership. – In compliance with the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make public offering through the stock exchanges of at least thirty percent (30%) of its common stock within a period of three (3) years from the date of effectivity of this Act: Provided, That no single person or entity shall be allowed to own more than five percent (5%) of the stock offerings."}},{"id":"PH-H6062-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"General Broadcast Policy Act. – The grantee shall comply with and be subject to the provisions of a general broadcast policy law that may hereafter be enacted."}},{"id":"PH-H6062-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Self-regulation by and Undertaking of Grantee. – The grantee shall not require any previous censorship of any speech, play, act, scene or other matter to be broadcast and/or telecast from its stations; but if any such speech, play, act, scene or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal, for such speech, play, act, scene or other matter: Provided, That the grantee, during any broadcast and telecast, shall cut off from the air the speech, play, act, scene or other matter being broadcast if the tendency thereof is to propose and/or incite treason, rebellion or sedition; or the language used therein or the theme thereof is indecent or immoral; and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H6062-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Warranty in Favor of National and Local Governments – The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H6062-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Sale, Lease, Transfer, Usufruct of Franchise . – The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or entity, nor merge with any other corporation or entity without the prior approval of the Congress of the Philippines. Neither shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is validly sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations provided for in this Act."}},{"id":"PH-H6062-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Separability Clause . – If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H6062-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Repealability and Non-exclusivity Clause. – This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H6062-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Reportorial Requirement. – The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H6062-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p86","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Radio Veritas-global Broadcasting System, Incorporated, A Franchise To Construct, Install, Operate and Maintain For Religious, Educational, Cultural and Commercial Purposes Radio and Television Broadcasting Stations in the Philippines, and For Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6063"] = {"id":"PH-H6063","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7580_1992.html","fetchedAt":"2026-10-06","articleCount":15,"structureMode":"ARTICLE","title":{"zh":"授予 South Cotabato 通信公司在南哥打巴托省境内建设、安装、运营和维护广播电视站的特许经营权法案","en":"An Act Granting the South Cotabato Communications Corporation A Franchise To Construct, Install, Operate and Maintain Radio and Television Broadcasting Stations Within the Province of South Cotabato","orig":"An Act Granting the South Cotabato Communications Corporation A Franchise To Construct, Install, Operate and Maintain Radio and Television Broadcasting Stations Within the Province of South Cotabato"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 7580","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-27","completenessNote":"全文，共 15 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7580_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6063-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. – Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the South Cotabato Communications Corporation, hereunder referred to as the grantee, its successors or assigns a franchise to construct, install, operate and maintain, for religious, educational, cultural and commercial purposes and in the public interest radio and television broadcasting stations within the Province of South Cotabato with the corresponding technological auxiliaries or facilities, special broadcast and other broadcast and distribution services and relay stations, and to install radio communication facilities for the grantee's private use in its broadcast services."}},{"id":"PH-H6063-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. – The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the other existing stations or stations which may be established by law without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H6063-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. – The grantee shall secure from the National Telecommunications Commission, hereinafter referred to as the Commission, the appropriate permits and licenses for its stations and shall not use any frequency in the radio/television spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H6063-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. – The grantee shall provide reasonable public service time to enable the Government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; promote public participation through community programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation to the detriment of the public interest, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H6063-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. – The President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, may temporarily take over and operate the stations of the grantee, temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or authorize the temporary use and operation thereof by any agency of the Government, upon due compensation to the grantee, for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H6063-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. – This franchise shall be for a term of twenty-five (25) years from the date of the effectivity of this Act, unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H6063-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. – Acceptance of this franchise shall be given in writing within sixty (60) days after approval of this Act. The grantee shall construct, complete and operate the radio or television stations within four (4) years from the date of the grantee's acceptance in writing of this franchise. Refusal or failure to accept the franchise or to operate within the prescribed period shall render the franchise void."}},{"id":"PH-H6063-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provisions. – The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the radio/television business transacted under this franchise by the grantee, its successors or assigns and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6063-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Self-regulation by and Undertaking of Grantee. – The grantee shall not require any previous censorship of any speech, play, act or scene, or other matter to be broadcast and/or telecast from its stations; but if any such speech, play, act or scene, or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal, for such speech, play, act or scene, or other matter: Provided, That the grantee, during any broadcast or telecast, shall cut off from the air the speech, play, act or scene, or other matter being broadcast if the tendency thereof is to propose and/or incite treason, rebellion or sedition; or the language used therein or the theme thereof is indecent or immoral or is inimical to public interest, necessity and convenience; and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H6063-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. – The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H6063-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. – The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such private person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H6063-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Separability Clause . – If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H6063-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Repealing and Non-exclusivity Clause. – This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the common good so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H6063-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"General Broadcast Policy. – The grantee shall comply with and be subject to the provisions of a general broadcast policy law that may hereafter be enacted."}},{"id":"PH-H6063-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p86","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the South Cotabato Communications Corporation A Franchise To Construct, Install, Operate and Maintain Radio and Television Broadcasting Stations Within the Province of South Cotabato","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6064"] = {"id":"PH-H6064","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7581_1992.html","fetchedAt":"2026-10-06","articleCount":24,"structureMode":"ARTICLE","title":{"zh":"通过稳定基本必需品与主要商品价格并对紧急情况及类似情形下的不合理涨价规定措施以保护消费者的法案","en":"An Act Providing Protection To Consumers By Stabilizing the Prices of Basic Necessities and Prime Commodities and By Prescribing Measures Against Undue Price Increases During Emergency Situations and Like Occasions","orig":"An Act Providing Protection To Consumers By Stabilizing the Prices of Basic Necessities and Prime Commodities and By Prescribing Measures Against Undue Price Increases During Emergency Situations and Like Occasions"},"level":"law","status":"active","topics":["trade","environment"],"docNumber":"Republic Act No. 7581","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-27","completenessNote":"全文，共 24 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7581_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6064-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title . – This Act shall be referred to as the \"Price Act.\""}},{"id":"PH-H6064-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Basic Policy. – It is the policy of the State to ensure the availability of basic necessities and prime commodities at reasonable prices at all times without denying legitimate business a fair return on investment. It is also a declared policy of the State to provide effective and sufficient protection to consumers against hoarding, profiteering and cartels with respect to the supply, distribution, marketing and pricing of said goods, especially during periods of calamity, emergency, widespread illegal price manipulation and other similar situations. To these ends, the State shall:\n1. Develop, adopt and promulgate measures to promote productivity in basic necessities and prime commodities;\n2. Develop an improved and efficient transport and distribution system;\n3. Develop, adopt and promulgate measures to stabilize prices at reasonable levels;\n4. Institute appropriate penalties for illegal price manipulation and other violations of this Act; and\n5. Establish a mechanism that will readily protect consumers from inadequate supply and unreasonable price increases on occasions of calamities, emergencies and like occurrences."}},{"id":"PH-H6064-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definition of Terms. – For purposes of this Act, the term:\n1. \"Basic necessities\" includes: rice; corn; bread; fresh, dried and canned fish and other marine products; fresh pork, beef and poultry meat; fresh eggs; fresh and processed milk; fresh vegetables; root crops; coffee; sugar; cooking oil; salt; laundry soap; detergents; firewood; charcoal; candles; and drugs classified as essential by the Department of Health;\n2. \"Buffer fund\" means a contingent fund in the budget of the implementing agency which shall not be used in its normal or regular operations but only for purposes provided for in this Act;\n3. \"Implementing agency\" means the department, agency or office of the Government which has jurisdiction over a basic necessity or prime commodity as defined in this Act, which shall be:\na. The Department of Agriculture, with reference to agricultural crops, fish and other marine products, fresh meat, fresh poultry and dairy products, fertilizers, and other farm inputs;\nb. The Department of Health, with reference to drugs;\nc. The Department of Environment and Natural Resources, with reference to wood and other forest products; and\nd. The Department of Trade and Industry, with reference to all other basic necessities and prime commodities.\n4. \"Panic-buying\" is the abnormal phenomenon where consumers buy basic necessities and prime commodities grossly in excess of their normal requirement resulting in undue shortages of such goods to the prejudice of less privileged consumers;\n5. \"Person\" means a natural person or a juridical person;\n6. \"Prevailing price\" means the average price at which any basic necessity has been sold in a given area within a month from the occurrence of any of the enumerated under Section 6 this Act;\n7. \"Price ceiling\" means the maximum price at which any basic necessity or prime commodity may be sold to the general public; and\n8. \"Prime commodities\" include fresh fruits; flour; dried, processed and canned pork; beef and poultry meat; dairy products not falling under basic necessities; noodles; onions; garlic; vinegar; patis; soy sauce; toilet soap; fertilizer; pesticides; herbicides; poultry; swine and cattle feeds; veterinary products for poultry, swine and cattle; paper; school supplies; nipa shingles; sawali; cement; clinker; GI sheets; hollow blocks; plywood; plyboard; construction nails; batteries; electrical supplies; light bulbs; steel wire; and all drugs not classified as essential drugs by the Department of Health."}},{"id":"PH-H6064-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Exclusion from the Coverage of this Act. – Upon petition of the concerned parties and after public hearing, the implementing agency, with the approval of the President, may exclude from the coverage of this Act, types or brands of the goods included in the definition of basic necessities and prime commodities, which may be deemed as nonessential goods or luxury goods: Provided, That, any type or brand so excluded may be reinstated by the implementing agency during occasions of acute shortage in the supply of the basic necessity or prime commodity to which the excluded type or brand used to belong."}},{"id":"PH-H6064-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Illegal Acts of Price Manipulation. – Without prejudice to the provisions of existing laws on goods not covered by this Act, it shall be unlawful for any person habitually engaged in the production, manufacture, importation, storage, transport, distribution, sale or other methods of disposition of goods to engage in the following acts of price manipulation of the price of any basic necessity or prime commodity:\n1. Hoarding, which is the undue accumulation by a person or combination of persons of any basic necessity or prime commodity beyond his or their normal inventory levels or the unreasonable limitation or refusal to dispose of, sell or distribute the stocks of any basic necessity or prime commodity to the general public or the unjustified taking out of any basic necessity or prime commodity from the channels of production, trade, commerce and industry. There shall be prima facie evidence of hoarding when a person has stocks of any basic necessity or prime commodity fifty percent (50%) higher than his usual inventory and unreasonably limits, refuses or fails to sell the same to the general public at the time of discovery of the stocks. The determination of a person's usual inventory shall be reckoned from the third month immediately preceding before the discovery of the stocks in case the person has been engaged in the business for at least three (3) months; otherwise, it shall be reckoned from the time he started his business;\n2. Profiteering, which is the sale or offering for sale of any basic necessity or prime commodity at a price grossly in excess of its true worth. There shall be prima facie evidence of profiteering whenever a basic necessity or prime commodity being sold: (a) has no price tag; (b) is misrepresented as to its weight or measurement; (c) is adulterated or diluted; or (d) whenever a person raises the price of any basic necessity or prime commodity he sells or offers for sale to the general public by more than ten percent (10%) of its price in the immediately preceding month: Provided, That, in the case of agricultural crops, fresh fish, fresh marine products, and other seasonal products covered by this Act and as determined by the implementing agency, the prima facie provision shall not apply; and\n3. Cartel, which is any combination of or agreement between two (2) or more persons engaged in the production, manufacture, processing, storage, supply, distribution, marketing, sale or disposition of any basic necessity or prime commodity designed to artificially and unreasonably increase or manipulate its price. There shall be prima facie evidence of engaging in a cartel whenever two (2) or more persons or business enterprises competing for the same market and dealing in the same basic necessity or prime commodity, perform uniform or complementary acts among themselves which tend to bring about artificial and unreasonable increase in the price of any basic necessity or prime commodity or when they simultaneously and unreasonably increase prices on their competing products thereby lessening competition among themselves."}},{"id":"PH-H6064-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Automatic Price Control. – Unless otherwise declared by the President, prices of basic necessities in an area shall automatically be frozen at their prevailing prices or placed under automatic price control whenever:\n1. That area is proclaimed or declared a disaster area or under a state of calamity;\n2. That area is declared under an emergency;\n3. The privilege of the writ of habeas corpus is suspended in that area;\n4. That area is placed tinder martial law;\n5. That area is declared to be in a state of rebellion; or\n6. A state of war is declared in that area.\nIf the prevailing price of any basic necessity is excessive or unreasonable, the implementing agency may recommend to the President the imposition of a price ceiling for the sale of the basic necessity at a price other than its prevailing price.\nUnless sooner lifted by the President, price control of basic necessities under this section shall remain effective for the duration of the condition that brought it about, but not for more than sixty (60) days.\nThe terms \"disaster\" and \"calamity\" shall include those brought about by natural or man-made causes, whether local or foreign."}},{"id":"PH-H6064-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Mandated Price Ceiling. – The President, upon the recommendation of the implementing agency, or the Price Coordinating Council, may impose a price ceiling on any basic necessity or prime commodity if any of the following conditions so warrants:\n1. The impendency, existence, or effects of a calamity;\n2. The threat, existence, or effects of an emergency;\n3. The prevalence or widespread acts of illegal price manipulation;\n4. The impendency, existence, or effect of any event that causes artificial and unreasonable increase in the price of the basic necessity or prime commodity; and\n5. Whenever the prevailing price of any basic necessity or prime commodity has risen to unreasonable levels."}},{"id":"PH-H6064-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Determination of Price Ceilings. – In determining the reasonable price ceiling, the following factors may be taken into consideration:\n1. The average price, in the last three (3) months immediately preceding the proclamation of the price ceiling, of the basic necessity or prime commodity under consideration;\n2. The supply available in the market;\n3. The cost to the producer, manufacturer, distributor or seller including but not limited to:\na. The exchange rate of the peso to the foreign currency with which a basic necessity or prime commodity or any component, ingredient or raw material thereof was paid for;\nb. Any change in the amortization cost of machinery brought about by any change in the exchange rate of the peso to the foreign currency with which the machinery was bought through credit facilities;\nc. Any change in the cost of labor brought about by a change in the minimum wage; and\nd. Any increase in the cost of transporting or distributing the basic necessity or prime commodity to the area of destination.\n4. Such other factors or conditions which will aid in arriving at a just and reasonable price ceiling."}},{"id":"PH-H6064-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Allocation of a Buffer Fund to the Implementing Agency. – The implementing agency may procure, purchase, import, or stockpile any basic necessity or prime commodity, devise ways and means of distributing them for sale at reasonable prices in areas where there is shortage of supply or a need to effect changes in its prevailing price. For any or all of these purposes, a buffer fund shall be allocated in the annual appropriations of the implementing agencies."}},{"id":"PH-H6064-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Powers and Responsibilities of Implementing Agencies. – To carry out the intents and purposes of this Act, the head of the implementing agency shall have the following additional powers and responsibilities:\n1. He shall, with the approval of the President, promulgate rules, regulations, and procedures for the implementation of this Act;\n2. He shall develop, promulgate and implement programs, projects or measures to promote productivity in all basic necessities and prime commodities under his agency's jurisdiction;\n3. He shall promote and facilitate the establishment of an effective procurement, storage, marketing and distribution system of basic necessities and prime commodities to ensure their availability in all areas of the country where they are needed;\n4. During instances of panic-buying, he may, with the approval of the President, institute temporary measures to ensure orderly and equitable distribution to consumers of basic necessities and prime commodities in the affected area;\n5. From time to time, he may issue suggested reasonable retail prices for any or all basic necessities and prime commodities under his jurisdiction for the information and guidance of producers, manufacturers, traders, dealers, sellers, retailers, and consumers;\n6. He shall cause the immediate dissemination of any mandated price ceiling for any basic necessity or prime commodity under his agency's jurisdiction through publication in a newspaper of general circulation in the area affected, and through broadcast by radio, or whenever deemed to materially make dissemination of the information more effective, by television. He may also cause the information to be disseminated through posting in public markets, supermarkets or other public places;\n7. He may, upon approval of the President, and subject to existing laws, rules and regulations on bidding, enter into any agreement with any local or foreign producer, manufacturer, supplier, distributor, or seller for the procurement of supplies or stocks of any basic necessity or prime commodity for purposes of buffer stocking: Provided, That, in areas where there are shortages or rampant illegal manipulation of prices, he may order their immediate sale;\n8. He may, subject to existing laws, rules and regulations on bidding, enter into any agreement with owners or operators of warehouses or storage houses or with owners, operators or franchise holders of vehicles or public utilities for the storage, transport, or distribution of any basic necessity or prime commodity;\n9. He may conduct investigations of any violation of this Act and, after due notice and hearing, impose administrative fines in such amount as he may deem reasonable which shall in no case be less than One thousand pesos (P1,000) nor more than One million pesos (P1,000,000). In the imposition of administrative fines, the following factors shall be taken into consideration:\na. Whether the subject of the violation is a basic necessity or a prime commodity; violations involving basic necessities shall be deemed more serious;\nb. Whether the subject of the violation is under price control under Sections 6 and 7 of this Act; violations involving basic necessities and prime commodities under price control shall be deemed more serious;\nc. The number of violations committed; respondents who had previously been found to have violated any of the provisions of this Act shall be imposed a higher fine; and\nd. Such other considerations as may be deemed necessary to carry out the intents, purposes and provisions of this Act;\n10. He may require the attendance and testimony of witnesses or the production of goods, objects, books, papers, documents, contracts, records, financial statements, accounts, agreements and such other evidences material in the determination of any violation of this Act;\n11. Without prejudice to the power to issue temporary closure or temporary restraining order for a period which shall not be more than ten (10) days, he may, after due notice and hearing issue cease and desist orders; reprimand; censure; suspend, revoke or cancel any permit, license, authority or registration issued by hi office; or order the permanent closure of any establishment violating the provisions of this Act;\n12. He may initiate summary proceedings to cause the seizure by the Government of basic necessities and prime commodities subject of a violation of this Act and order their sale to the public a reasonable prices whenever the nature of or the demand for such goods so requires: Provided, That, pending litigation, the proceeds of the sale shall be held in trust or escrow by the implementing agency: Provided, further, That, should the owner of the basic necessity or prime commodity seized and sold be found not liable for the violation which was the basis of the seizure, the proceeds from their sale shall be paid to him, otherwise, they shall accrue to the general fund of the Government and: Provided, finally, That, the head of the implementing agency shall cause the broadcast in radio or television and the publication in at least two (2) newspapers of general circulation of the fact of sale or disposition of such seized goods at least three (3) days before the date of sale or disposition;\n13. He may initiate action and cause the prosecution before the proper court of law of violators of this Act;\n14. He may deputize and enlist the assistance of any government official or agency in carrying out the provisions of this Act; and\n15. Such other functions and ancillary powers as may be necessary to effectively implement this Act."}},{"id":"PH-H6064-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Price Coordinating Council. – There is hereby created a Price Coordinating Council, hereinafter referred to as the Council, to be composed of the following members:\n1. The Secretary of Trade and Industry, as Chairman;\n2. The Secretary of Agriculture;\n3. The Secretary of Health;\n4. The Secretary of Environment and Natural Resources;\n5. The Secretary of Local Government;\n6. The Secretary of Transportation and Communications;\n7. The Secretary of Justice;\n8. The Director General of the National Economic and Development Authority;\n9. One (1) representative from the consumers' sector;\n10. One (1) representative from the agricultural producers' sector;\n11. One (1) representative from the trading sector; and\n12. One (1) representative from the manufacturers' sector.\nThe sectoral representatives of the Price Coordinating Council shall be appointed by the President for a term of one (1) year, without prejudice to reappointment for another term.\nThe Council shall meet every quarter and whenever the President or the Chairman shall convene the same. Each member shall receive reasonable reimbursements for transportation.\nMembers from the government sector may designate their representative to the Council.\nThe Department of Trade and Industry shall provide the secretariat to the Council from its existing organizational structure."}},{"id":"PH-H6064-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Functions of the Price Coordinating Council. – The Price Coordinating Council shall have the following functions:\n1. It shall coordinate the productivity, distribution and price stabilization programs, projects and measures of the Government and develop comprehensive strategies to effect a general stabilization of prices of basic necessities and prime commodities at affordable levels;\n2. It shall report to the President and to the Congress of the Philippines the status and progress of the programs, projects, and measures undertaken by each implementing department, agency or office as well as the comprehensive strategies developed by the Council to stabilize the prices of basic necessities and prime commodities;\n3. It shall advise the President on general policy matters for promotion and improvement in productivity, distribution and stabilization of prices of basic necessities and prime commodities;\n4. It may require from its members or any other government agency such information as it may deem necessary, and conduct public hearings for purposes of assessing the supply, distribution and price situation of any basic necessity or prime commodity;\n5. It shall publicize from time to time developments in productivity, supply, distribution and prices of basic necessities and prime commodities; and\n6. Whenever automatic price control of basic necessities is imposed under Section 6 of this Act, it shall cause the immediate dissemination of their prevailing prices or the price ceilings imposed in lieu thereof, as the case may be, through publication in a newspaper of general circulation in the area affected, and through broadcast by radio and, whenever the same is deemed to materially make dissemination of the information more effective, by television. It may also disseminate the information through posting in public markets, supermarkets and other public places."}},{"id":"PH-H6064-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The Price Action Officer. – Whenever the President deems it necessary, he may appoint any of the members of the Price Coordinating Council as Price Action Officer for the duration of the automatic price control under Section 6 of this Act who shall have the following powers and functions:\n1. He shall carry out, implement and enforce the policies and decisions of the Council;\n2. He shall coordinate the actions of all implementing agencies involved in the monitoring and investigation of abnormal price movements and shortages of basic necessities and prime commodities;\n3. He may call upon any official, agent, employee, agency or instrumentality of the national or local government for any other assistance that he may deem necessary to carry out the purposes of this Act;\n4. He shall establish linkages and coordinate with nongovernment or private organizations in the affected area to assist in the monitoring and implementation of price control therein; and\n5. He shall exercise such other functions and duties as may be given to him by the President."}},{"id":"PH-H6064-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Role of the National Statistics Office. – The National Statistics Office shall conduct independent periodic surveys and studies of the selling prices of all basic necessities and prime commodities all over the country as well as their share or effect on the family income of the different economic groups in the country for purposes of serving as data base for government efforts to stabilize prices, as well as evaluating the effectivity of the same."}},{"id":"PH-H6064-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Penalty for Acts of Illegal Price Manipulation. - Any person who commits any act of illegal price manipulation of any basic necessity or prime commodity under Section 5 hereof shall suffer the penalty of imprisonment for a period of not less than five (5) years nor more than fifteen (15) years, and shall be imposed a fine of not less than Five thousand pesos (P5,000) nor more than Two million pesos (P2,000,000)."}},{"id":"PH-H6064-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Penalty for Violation of Price Ceilings. – Any person who violates Section 6 or 7 of this Act shall suffer the penalty of imprisonment for a period of not less than one (1) year nor more than ten (10) years, or a fine of not less than Five thousand pesos (P5,000) nor more than One million pesos (P1,000,000), or both, at the discretion of the court."}},{"id":"PH-H6064-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Violation by Juridical Persons. – Whenever any violation of the provisions of this Act is committed by a juridical person, its officials or employees, or in case of a foreign corporation or association, its agent or representative in the Philippines who are responsible for the violation shall be held liable therefor."}},{"id":"PH-H6064-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Violation by Aliens. – In case of aliens, in addition to the penalty provided in Section 15 or 16 of this Act, the offender shall, upon conviction and after service of sentence, be immediately deported without need of any further proceedings."}},{"id":"PH-H6064-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Violation by Government Officials or Employees. – Any public official or employee who, by reason of his office, with or without consideration, conspires in the commission or knowingly conceals violations of any of the provisions of this Act shall likewise be principally responsible for the violation and shall suffer the additional penalty of permanent disqualification to hold public office."}},{"id":"PH-H6064-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Criminal Penalties Without Prejudice to Administrative Sanctions. – The foregoing criminal penalties shall be without prejudice to the administrative sanctions which the implementing agency may impose under this Act or under any other law."}},{"id":"PH-H6064-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Relation of the Price Act to Other Laws, Presidential Issuances. – Nothing in this Act shall be construed as removing or diminishing the jurisdiction of any agency of Government on certain goods or products conferred by other laws or presidential issuances."}},{"id":"PH-H6064-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Separability Clause . – If, for any reason, any provision of this Act or the application of such provision to any person, group or circumstance is declared invalid or unconstitutional, the remainder of this Act shall not be affected by such declaration."}},{"id":"PH-H6064-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Repealing Clause . – To the extent inconsistent with this Act, the following laws and letters of instruction are hereby repealed:\n1. Republic Act No. 4164, entitled \"An Act to Prevent the Excessive Increase in the Price of Certain Prime Necessities of Life on the Occasion of a Public Calamity, Penalizing the Violation Thereof, and for other Purposes\";\n2. Presidential Decree No. 1674, entitled \"Providing a Mechanism for Price Regulation, Creating a Price Stabilization Council, Prescribing its Powers and Responsibilities and for other Purposes;\"\n3. Letter of Instruction No. 1305, entitled 'Directing Measures to Prevent Cement Hoarding, Price Manipulation and Profiteering\";\n4. Letter of Instruction No. 1342, entitled \"Ordering Immediate Measures to Prevent Price Manipulation and to Protect Consumers\"; and\n5. Letter of Instruction No. 1359, entitled \"Directing Measures to Prevent Hoarding, Profiteering and Price Manipulation.\nAll laws, and rules and regulations inconsistent herewith are hereby likewise repealed or modified accordingly."}},{"id":"PH-H6064-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Effectivity Clause. – This Act shall take effect three (3) days after its publication in two (2) national newspapers of general circulation."}}],"pack":"ph-p86","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing Protection To Consumers By Stabilizing the Prices of Basic Necessities and Prime Commodities and By Prescribing Measures Against Undue Price Increases During Emergency Situations and Like Occasions","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6065"] = {"id":"PH-H6065","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7582_1992.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"将依第 3902 号共和国法授予 Consolidated Broadcasting System 在菲律宾建设、运营广播与电视台的特许权自本法批准之日续展二十五（25）年的法案","en":"An Act Renewing the Franchise Granted To the Consolidated Broadcasting System, Inc., Previously Known As the Audience, Incorporated, To Construct, Maintain and Operate Radio Broadcasting and Television Stations in the Philippines, Under Republic Act Numbered Thirty-nine Hundred and Two, To Another Twenty-five (25) Years From the Date of Approval of This Act","orig":"An Act Renewing the Franchise Granted To the Consolidated Broadcasting System, Inc., Previously Known As the Audience, Incorporated, To Construct, Maintain and Operate Radio Broadcasting and Television Stations in the Philippines, Under Republic Act Numbered Thirty-nine Hundred and Two, To Another Twenty-five (25) Years From the Date of Approval of This Act"},"level":"law","status":"active","topics":["investment","company"],"docNumber":"Republic Act No. 7582","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-27","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7582_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6065-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Renewal of Franchise. – The franchise of the Consolidated Broadcasting System, Inc., previously known as the Audience, Incorporated, its successors or assigns, hereinafter referred to as the grantee, to construct, maintain and operate radio broadcasting and television stations in the Philippines, under Republic Act Numbered Thirty-nine hundred and two, is hereby renewed to another twenty-five (25) years from the date of approval of this Act."}},{"id":"PH-H6065-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Integration of Republic Act No. 3902. – All the other provisions, terms and conditions contained in Republic Act No. 3902 are hereby made integral parts of this Act."}},{"id":"PH-H6065-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Public Ownership. – In compliance with the Constitutional mandate to democratize ownership of public utilities the herein grantee shall make public offering through the stock exchanges of at least thirty percent (30%) of its common stocks within a period of three (3) years from the date of effectivity of this Act: Provided, That no single person or entity shall be allowed to own more than five percent (5%) of the stock offerings."}},{"id":"PH-H6065-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Tax Provisions. – The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations which are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the radio/television business transacted under this franchise by the grantee, its successors or assigns and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code. The return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6065-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. – The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or entity, nor merge with any other corporation or entity without the prior approval of the Congress of the Philippines. Neither shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is validly sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H6065-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Repealing Clause . – The franchise hereby granted shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the common good so desires."}},{"id":"PH-H6065-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Reportorial Requirement. – The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H6065-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"General Broadcast Policy. – The grantee shall comply with and be subject to the provisions of a general broadcast policy law that may hereafter be enacted."}},{"id":"PH-H6065-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Separability Clause . – If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H6065-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Effectivity . – This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general"}}],"pack":"ph-p86","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Renewing the Franchise Granted To the Consolidated Broadcasting System, Inc., Previously Known As the Audience, Incorporated, To Construct, Maintain and Operate Radio Broadcasting and Television Stations in the Philippines, Under Republic Act Numbered Thirty-nine Hundred and Two, To Another Twenty-five (25) Years From the Date of Approval of This Act","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6066"] = {"id":"PH-H6066","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7583_1992.html","fetchedAt":"2026-10-06","articleCount":17,"structureMode":"ARTICLE","title":{"zh":"授予 Aboitiz Air Transport Corporation 设立、运营和维护国内与国际航空货物、邮件及其他财产运输服务的特许经营权法案","en":"An Act Granting the Aboitiz Air Transport Corporation A Franchise To Establish, Operate and Maintain Transport Services For the Carriage of Goods, Mail and Other Property By Air, Both Domestic and International","orig":"An Act Granting the Aboitiz Air Transport Corporation A Franchise To Establish, Operate and Maintain Transport Services For the Carriage of Goods, Mail and Other Property By Air, Both Domestic and International"},"level":"law","status":"active","topics":["investment","trade"],"docNumber":"Republic Act No. 7583","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-27","completenessNote":"全文，共 17 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7583_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6066-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. – Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Aboitiz Air Transport Corporation, hereunder referred to as the grantee, its successors or assigns a franchise to establish, operate and maintain transport services for the carriage of goods, mail and other property by air, both domestic and international.\nAir transport services shall include the maintenance and operation of hangars and aircraft services stations and facilities and other services of similar nature which may be necessary, convenient or useful as an auxiliary to aircraft transportation.\nThe grantee shall have the right at its terminals and landing fields, as well as in its aircraft, to construct, operate and maintain stations or transmitting sets for wireless telegraphy and direction findings, and other radio aids to air navigation, using wavelengths in accordance with the rules and regulations made from time to time by the proper agencies of the Government. The wireless communication facilities shall be used solely for receiving and transmitting weather forecasts and other matters in connection with the grantee's services."}},{"id":"PH-H6066-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Prior Approval of the Civil Aeronautics Board. - The grantee shall secure from the Civil Aeronautics Board the appropriate permits and licenses for its operations.\nAll aircraft used by the grantee including their accessories and equipment shall at all times be airworthy and the crew members shall be licensed by the Government of the Philippines. They shall be equipped with radio communication, safety and other equipment and shall be operated and maintained in accordance with the regulations and technical requirements of the Air Transportation Office or such other regulatory bodies as the Government may prescribe for this purpose.\nThe grantee's equipment and the operation of such equipment shall at all times be subject to inspection and regulation by the Air Transportation Office.\nThe grantee shall comply with the provisions of Republic Act Numbered Seven hundred and seventy-six, and the regulations promulgated thereunder from time to time."}},{"id":"PH-H6066-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Responsibility to the Public. – Excepting cases of force majeure and whenever weather conditions permit, the grantee shall maintain scheduled and/or nonscheduled and/or charter air transport services between Manila and any and all points and places throughout the Philippines and between Manila and other countries at such frequencies as traffic needs may require: Provided, however, That at least twenty-five percent (25%) of all frequencies shall be for the domestic market."}},{"id":"PH-H6066-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Rates for Services. – The grantee shall fix just and reasonable rates for the transportation of mail, goods and freight, subject to the regulations and approval of the Civil Aeronautics Board and other proper regulatory agencies of the Government."}},{"id":"PH-H6066-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Terms of Franchise. – This franchise shall be for a term of forty (40) years from the date of effectivity of this Act, unless sooner revoked or cancelled. In the event that the grantee fails to operate within two (2) years from the effectivity of this Act, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H6066-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Landing Facilities. – The grantee may use the landing and other airport facilities on land and water as may be maintained or owned by the Government within the Philippines on the grantee's lines subject to such terms and conditions, restrictions and national policy considerations as the Philippine Government may prescribe and, reciprocally, the Philippine Government shall have the right to use the landing and other airport facilities as may be maintained or owned by the grantee in the Philippines."}},{"id":"PH-H6066-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Contracts. – The grantee is authorized to enter into transportation contracts with the Philippine Government, including the carrying of mail, upon terms and conditions to be mutually agreed upon. The grantee shall give preferential consideration to contracts with the Philippine Government. The grantee may likewise enter into transportation maintenance and/or servicing contracts, and such other contracts relating to air transport with other foreign-owned airlines particularly with those which have international routes."}},{"id":"PH-H6066-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Right of Government. – In case of war, insurrection, domestic trouble, public calamity or national emergency, the Philippine Government, upon order of the President, shall have the right to take over and operate the equipment of the grantee, paying for its use or damages."}},{"id":"PH-H6066-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Public Equity Participation. – In compliance with the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make the public offering through the stock exchange of at least thirty percent (30%) of its common stock within a period of ten (10) years from the date of effectivity of this Act: Provided, That no single person or entity shall be allowed to own more than five percent (5%) of the stock offerings."}},{"id":"PH-H6066-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the operation of the services under the franchise hereby granted attributable solely to the act or omission of the grantee."}},{"id":"PH-H6066-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Tax Provisions. – In consideration of the franchise and the rights hereby granted, the grantee shall pay to the Philippine Government during the life of this franchise a franchise tax of five percent (5%) of the gross revenues derived by the grantee from transport operations.\nIn the event that any competing individual, partnership or corporation receives and enjoys tax privileges which tend to place the herein grantee at any disadvantage, then such provisions shall be deemed part hereof and shall operate equally in favor of the grantee.\nThe grantee shall, however, be subject to income tax levied under Title II of the National Internal Revenue Code, as amended, and tax on its real property under existing laws on revenues earned from activities other than air transportation."}},{"id":"PH-H6066-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Sale, Lease, Transfer, Assignment, Usufruct of Franchise. – The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation, or legal entity, nor merge with any other corporation or entity, without the prior approval of the Congress of the Philippines. Neither shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such private person, firm, company, corporation or entity without the prior approval of the Congress.\nAny person or entity to which this franchise is sold, transferred, or assigned shall be subject to all the conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H6066-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Legislative Amendment. – This franchise is subject to amendment or repeal by Congress when the common good so requires."}},{"id":"PH-H6066-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Separability Clause . – If any section or provision of this franchise is held or declared unconstitutional or invalid by a competent court in a final judgment, the other sections or provisions hereof shall continue to be in force as if the section or provision so annulled or voided had never been incorporated in this franchise."}},{"id":"PH-H6066-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Repealing Clause . – All laws, decrees, orders, instructions and rules and regulations, or parts thereof, which are inconsistent herewith are hereby repealed or modified accordingly."}},{"id":"PH-H6066-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Reportorial Requirement. – The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H6066-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days after its publication in at least two (2) national newspapers of general circulation."}}],"pack":"ph-p86","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Aboitiz Air Transport Corporation A Franchise To Establish, Operate and Maintain Transport Services For the Carriage of Goods, Mail and Other Property By Air, Both Domestic and International","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6067"] = {"id":"PH-H6067","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7584_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Tabango市","en":"An Act Establishing A High School in the Municipality of Tabango, Province of Leyte, To Be Known As the Pastor Salazar High School, and Appropriating Funds Therefor","orig":"An Act Establishing A High School in the Municipality of Tabango, Province of Leyte, To Be Known As the Pastor Salazar High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7584","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-27","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7584_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6067-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a public high school in Barangay Tabing, Municipality of Tabango, Province of Leyte, to be known as the Pastor Salazar High School."}},{"id":"PH-H6067-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H6067-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act is hereby authorized to be appropriated in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6067-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p86"};
  FT["PH-H6068"] = {"id":"PH-H6068","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7585_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立San Isidro市","en":"An Act Establishing A High School in the Municipality of San Isidro, Province of Leyte, To Be Known As the Muertigue High School, and Appropriating Funds Therefor","orig":"An Act Establishing A High School in the Municipality of San Isidro, Province of Leyte, To Be Known As the Muertigue High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7585","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-27","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7585_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6068-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a public high school in Barangay Daja, Municipality of San Isidro, Province of Leyte, to be known as the Muertigue High School."}},{"id":"PH-H6068-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H6068-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act is hereby authorized to be appropriated in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6068-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p86"};
  FT["PH-H6069"] = {"id":"PH-H6069","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7586_1992.html","fetchedAt":"2026-10-06","articleCount":24,"structureMode":"ARTICLE","title":{"zh":"规定国家综合保护区系统的建立与管理、界定其范围与覆盖并为其他目的法案","en":"An Act Providing for the Establishment and Management of National Integrated Protected Areas System, Defining Its Scope and Coverage, and for Other Purposes","orig":"An Act Providing for the Establishment and Management of National Integrated Protected Areas System, Defining Its Scope and Coverage, and for Other Purposes"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 7586","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-06-01","completenessNote":"全文，共 24 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7586_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6069-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title – This Act shall be known and referred to as the \"National Integrated Protected Areas System Act of 1992″."}},{"id":"PH-H6069-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy – Cognizant of the profound impact of man’s activities on all components of the natural environment particularly the effect of increasing population, resource exploitation and industrial advancement and recognizing the critical importance of protecting and maintaining the natural biological and physical diversities of the environment notably on areas with biologically unique features to sustain human life and development, as well as plant and animal life, it is hereby declared the policy of the State to secure for the Filipino people of present and future generations the perpetual existence of all native plants and animals through the establishment of a comprehensive system of integrated protected areas within the classification of national park as provided for in the Constitution.\nIt is hereby recognized that these areas, although distinct in features, posses common ecological values that may be incorporated into a holistic plan representative of our natural heritage; that effective administration of this area is possible only through cooperation among national government, local government and concerned private organizations; that the use and enjoyment of these protected areas must be consistent with the principles of biological diversity and sustainable development.\nTo this end, there is hereby established a National Integrated Protected Areas System (NIPAS), which shall encompass outstandingly remarkable areas and biologically important public lands that are habitats of rare and endangered species of plants and animals, biogeographic zones and related ecosystems, whether terrestrial, wetland or marine, all of which shall be designated as \"protected areas\"."}},{"id":"PH-H6069-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Categories – The following categories of protected areas are hereby established:\na. Strict nature reserve;\nb. Natural park;\nc. Natural monument;\nd. Wildlife sanctuary;\ne. Protected landscapes and seascapes;\nf. Resource reserve;\ng. Natural biotic areas; and\nh. Other categories established by law, conventions or international agreements which the Philippine Government is a signatory."}},{"id":"PH-H6069-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Definition of Terms – For purposes of this Act, the following terms shall be defined as follows:\n1. \"National Integrated Protected Areas System (NIPAS)\" is the classification and administration of all designated protected areas to maintain essential ecological processes and life-support systems, to preserve genetic diversity, to ensure sustainable use of resources found therein, and to maintain their natural conditions to the greatest extent possible;\n2. \"Protected Area\" refers to identified portions of land and water set aside by reason of their unique physical and biological significance, managed to enhance biological diversity and protected against destructive human exploitation;\n3. \"Buffer zones\" are identified areas outside the boundaries of and immediately adjacent to designated protected areas pursuant to Section 8 that need special development control in order to avoid or minimize harm to the protected area;\n4. \"Indigenous cultural community\" refers to a group of people sharing common bonds of language, customs, traditions and other distinctive cultural traits and who have since time immemorial, occupied, possessed and utilized a territory;\n5. \"National park\" refers to a forest reservation essentially of natural wilderness character which has been withdrawn from settlement, occupancy or any form of exploitation except in conformity with approved management plan and set aside as such exclusively to conserve the area or preserve the scenery, the natural and historic objects, wild animals and plants therein and to provide enjoyment of these features in such areas;\n6. \"Natural monuments\" is a relatively small area focused on protection of small features to protect or preserve nationally significant natural features on account of their special interest or unique characteristics;\n7. \"Natural biotic area\" is an area set aside to allow the way of life of societies living in harmony with the environment to adapt to modern technology at their pace;\n8. \"Natural park\" is a relatively large area not materially altered by human activity where extractive resource uses are not allowed and maintained to protect outstanding natural and scenic areas of national or international significance for scientific, educational and recreational use;\n9. \"Protected landscapes/seascapes\" are areas of national significance which are characterized by the harmonious interaction of man and land while providing opportunities for public enjoyment through the recreation and tourism within the normal lifestyle and economic activity of these areas;\n10. \"Resource reserve\" is an extensive and relatively isolated and uninhabited area normally with difficult access designated as such to protect natural resources of the area for future use and prevent or contain development activities that could affect the resource pending the establishment of objectives which are based upon appropriate knowledge and planning;\n11. \"Strict nature reserve\" is an area possessing some outstanding ecosystem, features and/or species of flora and fauna of national scientific importance maintained to protect nature and maintain processes in an undisturbed state in order to have ecologically representative examples of the natural environment available for scientific study, environmental monitoring, education, and for the maintenance of genetic resources in a dynamic and evolutionary state;\n12. \"Tenured migrant communities\" are communities within protected areas which have actually and continuously occupied such areas for five (5) years before the designation of the same as protected areas in accordance with this Act and are solely dependent therein for subsistence; and\n13. \"Wildlife sanctuary\" comprises an area which assures the natural conditions necessary to protect nationally significant species, groups of species, biotic communities or physical features of the environment where these may require specific human manipulations for their perpetuation."}},{"id":"PH-H6069-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Establishment and Extent of the System – The establishment and operationalization of the System shall involve the following:\n1. All areas or islands in the Philippines proclaimed, designated or set aside, pursuant to a law, presidential decree, presidential proclamation or executive order as national park, game refuge, bird and wildlife sanctuary, wilderness area, strict nature reserve, watershed, mangrove reserve, fish sanctuary, natural and historical landmark, protected and managed landscape/seascape as well as identified virgin forests before the effectivity of this Act are hereby designated as initial components of the System. The initial components of the System shall be governed by existing laws, rules and regulations, not inconsistent with this Act;\n2. Within one (1) year from the effectivity of this Act, the DENR shall submit to the Senate and the House of Representatives a map and legal descriptions or natural boundaries of each protected area initially comprising the System. Such maps and legal description shall, by virtue of this Act, constitute the official documentary representation of the entire System, subject to such changes as Congress deems necessary;\n3. All DENR records pertaining to said protected areas, including maps and legal descriptions or natural boundaries, copies of rules and regulations governing them, copies of public notices of, and reports submitted to Congress regarding pending additions, eliminations, or modifications shall be made available to the public. These legal documents pertaining to protected areas shall also be available to the public in the respective DENR Regional Offices, Provincial Environment and Natural Resources Offices (PENROs) and Community Environment and Natural Resources Offices (CENROs) where NIPAS areas are located;\n4. Within three (3) years from the effectivity of this Act, the DENR shall study and review each area tentatively composing the System as to its suitability or non-suitability for preservation as protected area and inclusion in the System according to the categories established in Section 3 hereof and report its findings to the President as soon as each study is completed. The study must include in each area:\n1. A forest occupants survey;\n2. An ethnographic study;\n3. A protected area resource profile;\n4. Land use plans done in coordination with the respective Regional Development Councils; and\n5. Such other background studies as will be sufficient bases for selection.\nThe DENR shall:\n1. Notify the public of proposed action through publication in a newspaper of general circulation, and such other means as the System deems necessary in the area or areas in the vicinity of the affected land thirty (30) days prior to the public hearing;\ni. Conduct public hearings at the locations nearest to the area affected; ii. At least thirty (30) days prior to the date of hearing, advise all Local Government Units (LGUs) in the affected areas, national agencies concerned, people’s organizations and non-government organizations and invite such officials to submit their views on the proposed action at the hearing not later than thirty (30) days following the date of hearing; and iii. Give due consideration to the recommendations at the public hearing; and provide sufficient explanation for his recommendations contrary to the general sentiments expressed in the public hearing;\n2. Upon receipt of the recommendations of the DENR, the President shall issue a presidential proclamation designating the recommended areas as protected areas and providing for measures for their protection until such time when Congress shall have enacted a law finally declaring such recommended areas as part of the integrated protected area systems; and\n3. Thereafter, the President shall send to the Senate and the House of Representatives his recommendations with respect to the designations as protected areas or reclassification of each area on which review has been completed, together with maps and legal description of boundaries. The President, in his recommendation, may propose the alteration of existing boundaries of any or all proclaimed protected areas, addition of any contiguous area of public land of predominant physical and biological value. Nothing contained herein shall limit the President to propose, as part of his recommendation to Congress, additional areas which have not been designated, proclaimed or set aside by law, presidential decree, proclamation or executive orders as protected area/s."}},{"id":"PH-H6069-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Additional Areas to be Integrated to the System. – Notwithstanding the establishment of the initial component of the additional areas with outstanding physical features, anthropological significance and biological diversity in accordance with the provisions of Section 5d."}},{"id":"PH-H6069-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Disestablishment as Protected Area. – When in the opinion of the DENR a certain protected area should be withdrawn or disestablished, or its boundaries modified as warranted by a study and sanctioned by the majority of the members of the respective boards for the protected area as herein established in Section 11, it shall, in turn, advice Congress. Disestablishment of a protected area under the System or modification of its boundary shall take effect pursuant to an act of Congress. Thereafter, said area shall revert to the category of public forests unless otherwise classified by Congress: Provided however, that after disestablishment by Congress, the Secretary may recommend the transfer of such disestablished area to other government agencies to serve other priority programs of national interest."}},{"id":"PH-H6069-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Buffer Zones. – For each protected area, there shall be established peripheral buffer zones when necessary, in the same manner as Congress establishes the protected area, to protect the same from activities that will directly and indirectly harm it. Such buffer zones shall be included in the individual protected area management plan that shall prepared for each protected area. The DENR shall exercise its authority over protected areas as provided in this Act on such area and designated as buffer zones."}},{"id":"PH-H6069-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Management Plans. – There shall be a general management planning strategy to serve as guide in formulating individual plans for each protected area. The management planning strategy shall, at the minimum, promote the adoption and implementation of innovative management techniques including if necessary, the concept of zoning, buffer zone management for multiple use and protection, habitat conservation and rehabilitation, diversity management, community organizing, socioeconomic and scientific researches, site-specific policy development, pest management, and fire control. The management planning strategy shall also provide guidelines for the protection of indigenous cultural communities, other tenured migrant communities and sites for close coordination between and among local agencies of the Government as well as the private sector.\nEach component area of the System shall be planned and administered to further protect and enhance the permanent preservation of its natural conditions. A management manual shall be formulated and developed which must contain the following: an individual management plan prepared by three (3) experts, basic background information, field inventory of the resources within the area, an assessment of assets and limitations, regional interrelationships, particular objectives for managing the area, appropriate division of the area into management zones, a review of the boundaries of the area, and a design of the management programs."}},{"id":"PH-H6069-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Administration and Management of the System. – The National Integrated Protected Areas System is hereby placed under the control and administration of the Department of Environment and Natural Resources. For this purpose, there is hereby created a division in the regional offices of the Department to be called the Protected Areas and Wildlife Division in regions where protected areas have been established, which shall be under the supervision of a Regional Technical Director, and shall include subordinate officers, clerks, and employees as may be proposed by the Secretary, duly approved by the Department of Budget and Management, and appropriated by the Congress. The Service thus established shall manage protected areas and promote the permanent preservation, to the greatest extent possible of their natural conditions.\nTo carry out the mandate of this Act, the Secretary of the DENR is empowered to perform any and all of the following acts:\na. To conduct studies on various characteristic features and conditions of the different protected areas, using commonalities in their characteristics, classify and define them into categories and prescribe permissible or prohibited human activities in each category in the System;\nb. To adopt and enforce a land use scheme and zoning plan in adjoining areas for the preservation and control of activities that may threaten the ecological balance in the protected areas;\nc. To cause the preparation of and exercise the power to review all plans and proposals for the management of protected areas;\nd. To promulgate rules and regulations necessary to carry out the provisions of this Act;\ne. To deputize field officers and delegate any of his powers under this Act and other laws to expedite its implementation and enforcement;\nf. To fix and prescribe reasonable NIPAS fees to be collected from government agencies or any person, firm or corporation deriving benefits from the protected areas;\ng. To exact administrative fees and fines as authorized in Section 21 for violation of guidelines, rules and regulations of this Act as would endanger the viability of protected areas;\nh. To enter into contracts and/or agreements with private entities or public agencies as may be necessary to carry out the purposes of this Act;\ni. To accept in the name of the Philippine Government and in behalf of NIPAS funds, gifts or bequests of money for immediate disbursements or other property in the interest of the NIPAS, its activities or its services;\nj. To call on any agency or instrumentality of the Government as well as academic institutions, non-government organizations and the private sector as may be necessary to accomplish the objectives and activities of the System;\nk. To submit an annual report to the President of the Philippines and to Congress on the status of protected areas in the country;\nl. To establish a uniform marker of the System, including an appropriate and distinctive symbol for each category in the System, in consultation with appropriate government agencies and public and private organizations;\nm. To determine the specification of the class, type and style of buildings and other structures to be constructed in protected areas and the materials to be used;\nn. Control the construction, operation and maintenance of roads, trails, waterworks, sewerage, fire protection, and sanitation systems and other public utilities within the protected area;\no. Control occupancy of suitable portions of the protected area and resettle outside of said area forest occupants therein, with the exception of the members of indigenous communities area; and\np. To perform such other functions as may be directed by the President of the Philippines, and to do such acts as may be necessary or incidental to the accomplishment of the purpose and objectives of the System."}},{"id":"PH-H6069-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Protected Area Management Board. – A Protected Area Management Board for each of the established protected area shall be created and shall be composed of the following: The Regional Executive Director under whose jurisdiction the protected area is located; one (1) representative from the autonomous regional government, if applicable; the Provincial Development Officer; one (1) representative from the municipal government; one (1) representative from each barangay covering the protected area; one (1) representative from each tribal community, if applicable; and, at least three (3) representatives from non-government organizations/local community organizations, and if necessary, one (1) representative from other departments or national government agencies involved in protected area management.\nThe Board shall, by a majority vote, decide the allocations for budget, approve proposals for funding, decide matters relating to planning, peripheral protection and general administration of the area in accordance with the general management strategy. The members of the Board shall serve for a term of five (5) years without compensation, except for actual and necessary traveling and subsistence expenses incurred in the performance of their duties. They shall be appointed by the Secretary of the DENR as follows:\na. A member who shall be appointed to represent each local government down to barangay level whose territory or portion is included in the protected area. Each appointee shall be the person designated by the head of such LGU, except for the Provincial Development Officer who shall serve ex officio;\nb. A member from non-government organizations who shall be endorsed by heads of organizations which are preferably based in the area or which have established and recognized interest in protected areas;\nc. The RED/s in the region/s where such protected area lies shall sit as ex officio member of the Board and shall serve as adviser/s in matters related to the technical aspect of management of the area; and\nd. The RED shall act as chairman of the Board. When there are two (2) or more REDs in the Board, the Secretary shall designate one (1) of them to be the Chairman. Vacancies shall be filled in the same manner as the original appointment."}},{"id":"PH-H6069-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Environmental Impact Assessment. – Proposals for activities which are outside the scope of the management plan for protected areas shall be subject to an environmental impact assessment as required by law before they are adopted, and the results thereof shall be taken into consideration in the decision-making process.\nNo actual implementation of such activities shall be allowed without the required Environmental Compliance Certificate (ECC) under the Philippine Environmental Impact Assessment (EIA) system. In instances where such activities are allowed to be undertaken, the proponent shall plan and carry them out in such manner as will minimize any adverse effects and take preventive and remedial action when appropriate. The proponent shall be liable for any damage due to lack of caution or indiscretion."}},{"id":"PH-H6069-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Ancestral Lands and Rights Over Them. – Ancestral lands and customary rights and interest arising shall be accorded due recognition. The DENR shall prescribe rules and regulations to govern ancestral lands within protected areas: Provided, that the DENR shall have so power to evict indigenous communities from their present occupancy nor resettle them to another area without their consent: Provided, however, That all rules and regulations, whether adversely affecting said communities or not, shall be subjected to notice and hearing to be participated in by members of concerned indigenous community."}},{"id":"PH-H6069-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Survey for Energy Resources. – Consistent with the policies declared in Section 2 hereof, protected areas, except strict nature reserves and natural parks, may be subjected to exploration only for the purpose of gathering information on energy resources and only if such activity is carried out with the least damage to surrounding areas. Surveys shall be conducted only in accordance with a program approved by the DENR, and the result of such surveys shall be made available to the public and submitted to the President for recommendation to Congress. Any exploitation and utilization of energy resources found within NIPAS areas shall be allowed only through a law passed by Congress."}},{"id":"PH-H6069-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Areas Under the Management of Other Departments and Government Instrumentalities. – Should there be protected areas, or portions thereof, under the jurisdiction of government instrumentalities other than the DENR, such jurisdiction shall, prior to the passage of this Act, remain in the said department or government instrumentality; Provided, That the department or government instrumentality exercising administrative jurisdiction over said protected area or a portion thereof shall coordinate with the DENR in the preparation of its management plans, upon the effectivity of this Act."}},{"id":"PH-H6069-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Integrated Protected Areas Fund. – There is hereby established a trust fund to be known as Integrated Protected Areas (IPAS) Fund for purposes of financing projects of the System. The IPAS may solicit and receive donations, endowments, and grants in the form of contributions, and such endowment shall be exempted from income or gift taxes and all other taxes, charges or fees imposed by the Government or any political subdivision or instrumentality thereof.\nAll incomes generated from the operation of the System or management of wild flora and fauna shall accrue to the Fund and may be utilized directly by the DENR for the above purpose. These incomes shall be derived from:\na. Taxes from the permitted sale and export of flora and fauna and other resources from protected areas;\nb. Proceeds from lease of multiple use areas;\nc. Contributions from industries and facilities directly benefiting from the protected area; and\nd. Such other fees and incomes derived from the operation of the protected area. Disbursements from the Funds shall be made solely for the protection, maintenance, administration, and management of the System, and duly approved projects endorsed by the PAMBs, in the amounts authorized by the DENR."}},{"id":"PH-H6069-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Annual Report to Congress. – At the opening of each session of Congress, the DENR shall report to the President, for transmission to Congress, on the status of the System, regulation in force and other pertinent information, together with recommendations."}},{"id":"PH-H6069-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Field Officers. – All officials, technical personnel and forest guards employed in the integrated protected area service or all persons deputized by the DENR, upon recommendation of the Management Board shall be considered as field officers and shall have the authority to investigate and search premises and buildings and make arrests in accordance with the rules on criminal procedure for the violation of laws and regulations relating to the protected areas. Persons arrested shall be brought to the nearest police precinct for investigation.\nNothing herein mentioned shall be construed as preventing regular law enforcers and police officers from arresting any person in the act of violating said laws and regulations."}},{"id":"PH-H6069-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Special Prosecutors. – The Department of Justice shall designate special prosecutors to prosecute violations of laws, rules and regulations in protected areas."}},{"id":"PH-H6069-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Prohibited Acts. – Except as may be allowed by the nature of their categories and pursuant to rules and regulations governing the same, the following acts are prohibited within protected areas:\na. Hunting, destroying, disturbing, or mere possession of any plants or animals or products derived therefrom without a permit from the Management Board;\nb. Dumping of any waste products detrimental to the protected area, or to the plants and animals or inhabitants therein;\nc. Use of any motorized equipment without a permit from the Management Board;\nd. Mutilating, defacing or destroying objects of natural beauty, or objects of interest to cultural communities (of scenic value);\ne. Damaging and leaving roads and trails in a damaged condition;\nf. Squatting, mineral locating, or otherwise occupying any land;\ng. Constructing or maintaining any kind of structure, fence or enclosures, conducting any business enterprise without a permit;\nh. Leaving in exposed or unsanitary conditions refuse or debris, or depositing in ground or in bodies of water; and\ni. Altering, removing destroying or defacing boundary marks or signs."}},{"id":"PH-H6069-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Penalties. – Whoever violates this Act or any rules and regulations issued by the Department pursuant to this Act or whoever is found guilty by a competent court of justice of any of the offenses in the preceding section shall be fined in the amount of not less than Five thousand pesos (P5,000) nor more than Five hundred thousand pesos (P500,000), exclusive of the value of the thing damaged or imprisonment for not less than one (1) year but not more than six (6) years, or both, as determined by the court: Provided, that, if the area requires rehabilitation or restoration as determined by the court, the offender shall be required to restore or compensate for the restoration to the damages: Provided, further, that court shall order the eviction of the offender from the land and the forfeiture in favor of the Government of all minerals, timber or any species collected or removed including all equipment, devices and firearms used in connection therewith, and any construction or improvement made thereon by the offender. If the offender is an association or corporation, the president or manager shall be directly responsible for the act of his employees and laborers: Provided, finally, that the DENR may impose administrative fines and penalties consistent with this Act."}},{"id":"PH-H6069-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Separability Clause. – If any part or section of this Act is declared unconstitutional, such declaration shall not affect the other parts or sections of this Act."}},{"id":"PH-H6069-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Repealing Clause. – All laws, presidential decrees, executive orders, rules and regulations inconsistent with any provisions of this Act shall be deemed repealed or modified accordingly."}},{"id":"PH-H6069-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days after its complete publication in two (2) newspapers of general circulation."}}],"pack":"ph-p86","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment and Management of National Integrated Protected Areas System, Defining Its Scope and Coverage, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6070"] = {"id":"PH-H6070","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7587_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Linapacan市","en":"An Act Converting the Rural Health Unit in the Municipality of Linapacan, Province of Palawan, Into A Five-bed Capacity Health Infirmary, To Be Known As the Linapacan Health Infirmary, and Appropriating Funds Therefor","orig":"An Act Converting the Rural Health Unit in the Municipality of Linapacan, Province of Palawan, Into A Five-bed Capacity Health Infirmary, To Be Known As the Linapacan Health Infirmary, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7587","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-06-01","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7587_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6070-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The rural health unit in the Municipality of Linapacan, Province of Palawan, is hereby converted into a five-bed capacity health infirmary, to be known as the Linapacan Health Infirmary."}},{"id":"PH-H6070-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6070-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p86"};
