  FT["PH-H6079"] = {"id":"PH-H6079","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7597_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将Dapitan市黎刹纪念区医院床位由75张增至100张并为此拨款的法案","en":"An Act Increasing the Bed Capacity of the Rizal Memorial District Hospital in Dapitan City From Seventy-five (75) To One Hundred (100) Beds, and Appropriating Funds Therefor","orig":"An Act Increasing the Bed Capacity of the Rizal Memorial District Hospital in Dapitan City From Seventy-five (75) To One Hundred (100) Beds, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7597","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-06-02","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7597_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6079-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Rizal Memorial District Hospital in Dapitan City is hereby increased from seventy-five (75) to one hundred (100) beds."}},{"id":"PH-H6079-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6079-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 2, 1992."}}],"pack":"ph-p86","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of the Rizal Memorial District Hospital in Dapitan City From Seventy-five (75) To One Hundred (100) Beds, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6080"] = {"id":"PH-H6080","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7598_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Pinamungajan市","en":"An Act Converting the Rural Health Unit in the Municipality of Pinamungajan, Province of Cebu, Into A Five-bed Capacity Health Infirmary, To Be Known As Pinamungajan Health Infirmary, and Appropriating Funds Therefor","orig":"An Act Converting the Rural Health Unit in the Municipality of Pinamungajan, Province of Cebu, Into A Five-bed Capacity Health Infirmary, To Be Known As Pinamungajan Health Infirmary, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7598","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-06-02","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7598_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6080-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The rural health unit in the Municipality of Pinamungajan, Province of Cebu, is hereby converted into a five-bed capacity health infirmary, to be known as the Pinamungajan Health Infirmary."}},{"id":"PH-H6080-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6080-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p86"};
  FT["PH-H6081"] = {"id":"PH-H6081","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7599_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将巴拉望省Cuyo市镇Cuyo区医院床位由50张增至75张并为此拨款的法案","en":"An Act Increasing the Bed Capacity of the Cuyo District Hospital in the Municipality of Cuyo, Province of Palawan, From Fifty (50) To Seventy-five (75) Beds, and Appropriating Funds Therefore","orig":"An Act Increasing the Bed Capacity of the Cuyo District Hospital in the Municipality of Cuyo, Province of Palawan, From Fifty (50) To Seventy-five (75) Beds, and Appropriating Funds Therefore"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7599","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-06-03","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7599_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6081-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Cuto District Hospital in the Municipality of Cuyo, Province of Palawan, is hereby increased from fifty 50) to seventy-five (75) beds."}},{"id":"PH-H6081-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following is enactment into law thereafter."}},{"id":"PH-H6081-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall effect upon its approval."}}],"pack":"ph-p86","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of the Cuyo District Hospital in the Municipality of Cuyo, Province of Palawan, From Fifty (50) To Seventy-five (75) Beds, and Appropriating Funds Therefore","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6082"] = {"id":"PH-H6082","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7600_1992.html","fetchedAt":"2026-10-06","articleCount":18,"structureMode":"ARTICLE","title":{"zh":"对采取母婴同室与母乳喂养做法的所有公立与私立卫生机构给予激励并为其他目的法案","en":"An Act Providing Incentives To All Government and Private Health Institutions With Rooming-in and Breastfeeding Practices and For Other Purposes","orig":"An Act Providing Incentives To All Government and Private Health Institutions With Rooming-in and Breastfeeding Practices and For Other Purposes"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7600","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-06-02","completenessNote":"全文，共 18 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7600_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6082-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title .—This Act shall be known as \"The Rooming-In and Breastfeeding Act of 1992\"."}},{"id":"PH-H6082-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy .—The State adopts room-ing-in as a national policy to encourage, protect and support the practice of breastfeeding. It shall create an environment where basic physical, emotional, and psychological needs of mothers and infants are fulfilled through the practice of rooming-in and breastfeeding.\nBreastfeeding has distinct advantages which benefit the infant and the mother including the hospital and the country that adopt its practice. It is the first preventive health measure that can be given to the child at birth. It also enhances mother-infant relationship. Furthermore, the practice of breastfeeding could save the country valuable foreign exchange that may otherwise be used for milk importation.\nBreastmilk is the best food since it contains essential nutrients completely suitable for the infant's needs. It is also nature's first immunization, enabling the infant to fight potential serious infection. It contains growth factors that enhance the maturization of an infants organ systems."}},{"id":"PH-H6082-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definition of Terms. —For purposes of this Act, the following definitions are adopted:\na) Age of gestation —the length of time the fetus is inside the mother's womb.\nb) Bottlefeeding —the method of feeding an infant using a bottle with artificial nipples, the contents of which can be any type of fluid.\nc) Breastfeeding —the method of feeding an infant directly from the human breast.\nd) Breastmilk —the human milk from a mother.\ne) Expressed breastmilk —the human milk which has been extracted from the breast by hand or by breast pump. It can be fed to an infant using a dropper, a nasogatric tube, a cup and spoon, or a bottle.\nf) Formula feeding —the feeding of a newborn with infant formula usually by bottlefeeding. It is also called artificial feeding.\ng) Health institutions —are hospitals, health infirmaries, health centers, lying-in centers, or puericulture centers with obstetrical and pediatric services,\nh) Health personnel —are professionals and workers who manage and/or administer the entire operation of health institutions and/or who are involved in providing maternal and child health services.\n(i) Infant —a child within zero (0) to twelve (12) months of age.\nj) Infant formula —the breastmilk substitute formulated industrially in accordance with applicable Codex Alimentarius standards, to satisfy the normal nutritional requirements of infants up to six (6) months of age, and adopted to their physiological characteristics.\nk) Lactation management —the general care of a mother-infant nursing couple during the mother's prenatal, immediate postpartum and postnatal periods. It deals with educating and providing knowledge and information to pregnant and lactating mothers on the advantages of breastfeeding, the physiology of lactation, the establishment and maintenance of lactation, the proper care of the breasts and nipples, and such rother matters that would contribute to successful breastfeeding.\nl) Low birth weight infant —a newborn weighing less than two thousand five hundred (2,500) grams at birth.\nm) Mother's milk —the breastmilk from the newborn's own mother.\nn) Rooming-in -the practice of placing the newborn in the same room as the mother right after delivery up to discharge to facilitate mother-infant bonding and to initiate breastfeeding. The infant may either share the mother's bed or be placed in a crib beside the mother.\no) Seriously ill mothers —are those who are: with severe infections; in shock; in severe cardiac or respiratory distress; or dying; or those with other conditions that may be determined by the attending physician as serious.\np) Wet-nursing —the feeding of a newborn from another mother's breast when his/her own mother cannot breastfeed.\nCHAPTER I\nROOMING-IN AND BREASTFEEDING OF INFANTS"}},{"id":"PH-H6082-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Applicability. —The provisions in this Chapter shall apply to all private and government health institutions adopting rooming-in and breastfeeding as denned in this Act"}},{"id":"PH-H6082-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Normal Spontaneous Deliveries. —The following newborn infants shall be put to the breast of the mother immediately after birth and forthwith roomed-in within thirty (SO) minutes:\na) well infants regardless of age of gestation; and\nb) infants with low birth weights but who can suck."}},{"id":"PH-H6082-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Deliveries by Caesarian. —Infants delivered by Caesarian section shall be roomed-in and breastfed within three (3) to four (4) hours after birth."}},{"id":"PH-H6082-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Deliveries Outside Health Institutions. —New-borns delivered outside health institutions whose mothers have been admitted to the obstetrics department/unit and who both meet the general conditions stated in Section 5 of this Act, shall be roomed-in and breastfed immediately."}},{"id":"PH-H6082-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Exemptions. —Infants whose conditions do not permit rooming-in and breastfeeding as determined, by the attending physician, and infants whose mothers are either: a) seriously ill; b) taking medications contraindicated to breastfeeding; c) violent psychotics; or d) whose conditions do not permit breastfeeding and rooming-in as determined by the physician shall be exempted from the provisions of Sections 5, 6, and 7: Provided, That these infants shall be fed expressed breastmilk or wet-nursed as may be determined by the attending physician."}},{"id":"PH-H6082-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Right of the Mother to Breastfeed. —It shall be the mother's right to breastfeed her child who equally has the right to her breastfmilk. Bottlefeeding shall be allowed only after the mother has been informed by the attending health personnel of the advantages of breastfeeding and the proper techniques of infant formula feeding and the mother has opted in writing to adopt infant formula feeding for her infant.\nCHAPTER II\nHUMAN MILK BANK"}},{"id":"PH-H6082-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Provision of Facilities for Breast-milk Collection and Storage. —The health institution adopting rooming-in and breastfeeding shall provide equipment, facilities, and supplies for breastmilk collection, storage and utilization, the standards of which shall be defined by the Department of Health.\nCHAPTER III\nINFORMATION, EDUCATION AND RE-EDUCATION DRIVE"}},{"id":"PH-H6082-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Continuing Education, lie-education and Training of Health Personnel. —The Department of Health with the assistance of other government agencies, professional and non-governmental organizations shall conduct continuing information, education, re-education, and training programs for physicians, nurses, midwives, nutritionist-dietitians, community health workers and traditional birth attendants (TBAs) and other health personnel, on current and updated lactation management.\nInformation materials shall be given to all health personnel involved in maternal and infant care in health institutions."}},{"id":"PH-H6082-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Information Dissemination to Pregnant Women. —During the prenatal, perinatal and postnatal consultations and/or confinements of the mothers or pregnant women in a health institution, it shall be the obligation of the health institution and the health personnel to immediately and continuously teach, train, and support the women on current and updated lactation management and infant care, through participatory strategies such as organization of mothers' clubs and breastfeeding support groups and to distribute written information materials on such matters free of charge.\nCHAPTER IV\nMISCELLANEOUS PROVISIONS"}},{"id":"PH-H6082-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Incentives. —The expenses incurred by a private health institution in complying with the provisions of this Act, shall be deductible expenses for income tax purposes up to twice the actual amount incurred: Provided, That the deduction shall apply for the taxable period when the expenses were incurred: Provided, further, That the hospital shall/comply with the provisions of this Act within six (6) months after its approval.\nGovernment health institutions shall receive an additional appropriation equivalent to the savings they may derive as a result of adopting rooming-in arid breastfeeding. The additional appropriation shall be included in their budget fcr the next fiscal year."}},{"id":"PH-H6082-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Sanctions. —The Secretary of Health is hereby empowered to impose sanctions for the violation of this Act and the rules issued thereunder. Such sanctions may be in the form of reprimand or censure and in case of repeated willful, violations, suspension of the permit to operate of the erring health institution."}},{"id":"PH-H6082-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Rules and Regulations. —The Secretary of Health, in consultation with other government agencies, professional and non-governmental organizations concerned shall promulgate the rules and regulations necessary to carry out the provisions of this Act."}},{"id":"PH-H6082-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Repealing Clause .—All acts, laws, decrees, executive orders, rules and regulations or parts thereof, which are contrary to or inconsistent with this Act are hereby repealed, amended, or modified accordingly."}},{"id":"PH-H6082-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Separability Clause .—If any clause, sentence, paragraph or part of this Act shall be declared to be invalid, the remainder of this Act or any provision not affected thereby shall remain in force and effect."}},{"id":"PH-H6082-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Effectivity —This Act shall take effect .one hundred twenty (120) days after publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p86","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing Incentives To All Government and Private Health Institutions With Rooming-in and Breastfeeding Practices and For Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6083"] = {"id":"PH-H6083","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7601_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"宣布每年2月11日为Evelio B. Javier州长日，即安蒂克、卡皮斯、阿克兰与伊洛伊洛四省的特别非工作公共假日的法案","en":"An Act Declaring February 11 of Each Year Governor Evelio B. Javier Day, A Special Nonworking Public Holiday in the Provinces of Antique, Capiz, Aklan and Iloilo","orig":"An Act Declaring February 11 of Each Year Governor Evelio B. Javier Day, A Special Nonworking Public Holiday in the Provinces of Antique, Capiz, Aklan and Iloilo"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7601","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-06-03","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7601_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6083-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"In order to commemorate the death anniversary of the late Governor Evelio B. Javier, February Eleven of each year is hereby declared Governor Evelio B. Javier Day, a special nonworking public holiday in the Provinces of Antique, Capiz, Aklan and Iloilo."}},{"id":"PH-H6083-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p86","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Declaring February 11 of Each Year Governor Evelio B. Javier Day, A Special Nonworking Public Holiday in the Provinces of Antique, Capiz, Aklan and Iloilo","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
